const publicMonths=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const publicState={events:[],partners:[],year:new Date().getFullYear(),partnerIndex:0};
const publicEscape=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const publicDate=value=>new Date(`${String(value).slice(0,10)}T12:00:00`);
const publicInitials=name=>String(name||'AF').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
function renderPublicCalendar(){
  const calendar=document.querySelector('[data-public-calendar]');
  calendar.innerHTML=publicMonths.map((month,index)=>{const events=publicState.events.filter(event=>publicDate(event.startDate).getFullYear()===publicState.year&&publicDate(event.startDate).getMonth()===index);return `<article class="public-month"><h3>${month}</h3>${events.length?events.map(event=>`<div class="public-event"><time>${publicDate(event.startDate).getDate()} ${month.slice(0,3).toUpperCase()}</time><strong>${publicEscape(event.title)}</strong><span>${publicEscape([event.timeLabel,event.location].filter(Boolean).join(' · '))}</span></div>`).join(''):'<span class="public-month-empty">Sem programação publicada.</span>'}</article>`}).join('');
}
function renderPublicPartners(){const track=document.querySelector('[data-public-partners]');track.innerHTML=publicState.partners.length?publicState.partners.map(partner=>`<article class="public-partner-card"><div class="public-partner-logo">${partner.logoData?`<img src="${partner.logoData}" alt="Logo de ${publicEscape(partner.companyName)}">`:`<span>${publicEscape(publicInitials(partner.companyName))}</span>`}</div><h4>${publicEscape(partner.companyName)}</h4><p>${publicEscape(partner.niche||'Parceiro da Fonte do Empreendedor')}</p></article>`).join(''):'<article class="public-partner-empty">Os novos parceiros aparecerão aqui.</article>';movePartners(0)}
function movePartners(delta){const track=document.querySelector('[data-public-partners]');const cards=[...track.querySelectorAll('.public-partner-card')];if(!cards.length)return;publicState.partnerIndex=Math.max(0,Math.min(cards.length-1,publicState.partnerIndex+delta));const gap=parseFloat(getComputedStyle(track).gap)||0;track.style.transform=`translate3d(${-publicState.partnerIndex*(cards[0].getBoundingClientRect().width+gap)}px,0,0)`}
document.querySelector('[data-partner-prev]').addEventListener('click',()=>movePartners(-1));document.querySelector('[data-partner-next]').addEventListener('click',()=>movePartners(1));addEventListener('resize',()=>movePartners(0),{passive:true});
fetch('/api/public-data').then(async response=>{if(!response.ok)throw new Error();return response.json()}).then(data=>{publicState.events=data.events||[];publicState.partners=data.partners||[];const years=new Set([new Date().getFullYear()-1,new Date().getFullYear(),new Date().getFullYear()+1,...publicState.events.map(event=>publicDate(event.startDate).getFullYear())]);const select=document.querySelector('[data-public-year]');select.innerHTML=[...years].sort().map(year=>`<option value="${year}">${year}</option>`).join('');select.value=String(publicState.year);select.addEventListener('change',()=>{publicState.year=Number(select.value);renderPublicCalendar()});renderPublicCalendar();renderPublicPartners()}).catch(()=>{document.querySelector('[data-public-calendar]').innerHTML='<p class="data-error">A programação está temporariamente indisponível.</p>'});
